package csd230.lab1.entities;

import jakarta.persistence.*;
import java.util.LinkedHashSet;
import java.util.Set;

/**
 * Represents a shopping cart entity mapped to the "cart_entity" table.
 * Demonstrates a Many-to-Many relationship with ProductEntity.
 */
@Entity
@Table(name = "cart_entity")
public class CartEntity {

    /**
     * Unique identifier for the Cart. Automatically generated by the database.
     */
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    @Column(name = "id", nullable = false)
    private Long id;

    /**
     * Many-to-Many relationship between CartEntity and ProductEntity.
     * Uses LinkedHashSet to prevent duplicate entries while preserving insertion order.
     * The join table "cart_products" stores foreign keys: cart_id and product_id.
     */
    @ManyToMany(cascade = {CascadeType.PERSIST, CascadeType.MERGE})
    @JoinTable(
            name = "cart_products",
            joinColumns = @JoinColumn(name = "cart_id"),
            inverseJoinColumns = @JoinColumn(name = "product_id")
    )
    private Set<ProductEntity> products = new LinkedHashSet<>();

    /**
     * Default no-argument constructor required by JPA.
     */
    public CartEntity() {
    }

    /**
     * Convenience helper method to add a product to the cart.
     * Automatically maintains bidirectional relationship integrity on both sides.
     *
     * @param product ProductEntity to be added to this cart
     */
    public void addProduct(ProductEntity product) {
        this.products.add(product);
        product.getCarts().add(this); // Maintain relationship link on both sides
    }

    // Getters and Setters

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public Set<ProductEntity> getProducts() {
        return products;
    }

    public void setProducts(Set<ProductEntity> products) {
        this.products = products;
    }

    @Override
    public String toString() {
        return "CartEntity{" +
                "id=" + id +
                ", totalProducts=" + (products != null ? products.size() : 0) +
                '}';
    }
}